#!/usr/bin/env node
/**
 * scripts/set-build-mode.mjs — Build-time IRU mode injection.
 *
 * Runs as the npm `prebuild` hook (package.json), so it executes on every
 * `npm run build` — including Vercel builds — before Vite compiles.
 *
 * Source of truth, in priority order:
 *   1. VITE_IRU_MODE env var (explicit override; local dev or dashboard).
 *   2. VERCEL_GIT_COMMIT_REF === 'institutional' (Vercel branch build).
 *   3. Default 'consumer'.
 *
 * Writes two generated files (both committed with the 'consumer' default
 * so local dev, typecheck, and tests work without a build):
 *   - src/build-mode.ts   (client: imported by src/institutional.ts)
 *   - api/build-mode.json (server: read by api/fill.py and the JS
 *     serverless functions via api/_lib/server-mode.js)
 *
 * The institutional branch IS the staff-mode app, so its Vercel Preview
 * build resolves to 'institutional' from the branch ref alone — no
 * dashboard env var is needed. The consumer (DTC) branch resolves to
 * 'consumer' the same way. Never hardcode a mode in application code.
 */
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

const envMode = (process.env.VITE_IRU_MODE || '').trim().toLowerCase();
const branch = (process.env.VERCEL_GIT_COMMIT_REF || '').trim();
const mode = envMode === 'institutional' || envMode === 'consumer'
  ? envMode
  : branch === 'institutional'
    ? 'institutional'
    : 'consumer';

const tsContent = `// Generated by scripts/set-build-mode.mjs at build time. Do not edit by hand.
// Committed default is 'consumer'; the prebuild hook regenerates this file
// on Vercel from VITE_IRU_MODE or the branch ref (VERCEL_GIT_COMMIT_REF).
export const BUILD_MODE: 'consumer' | 'institutional' = '${mode}';
`;
const jsonContent = `{"mode": "${mode}"}\n`;

writeFileSync(join(root, 'src', 'build-mode.ts'), tsContent);
writeFileSync(join(root, 'api', 'build-mode.json'), jsonContent);
console.log(`[iru] build mode: ${mode} (VITE_IRU_MODE=${envMode || '(unset)'}, branch=${branch || '(unset)'})`);
